<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Brittle Star on a Barrel Sponge</title>
  <style>
    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      background:
        radial-gradient(circle at 50% 35%, #174b50 0%, #082d35 45%, #031920 100%);
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      touch-action: none;
      cursor: grab;
    }

    canvas:active {
      cursor: grabbing;
    }

    .caption {
      position: fixed;
      top: 28px;
      left: 30px;
      z-index: 2;
      color: #e7f4e9;
      pointer-events: none;
      text-shadow: 0 2px 18px rgba(0, 30, 35, 0.65);
    }

    .caption h1 {
      margin: 0;
      font-size: clamp(22px, 3vw, 38px);
      font-weight: 400;
      letter-spacing: 0.04em;
    }

    .caption p {
      margin: 7px 0 0;
      color: rgba(221, 241, 231, 0.7);
      font-size: 12px;
      letter-spacing: 0.18em;
      text-transform: uppercase;
    }

    .hint {
      position: fixed;
      right: 24px;
      bottom: 20px;
      z-index: 2;
      padding: 9px 13px;
      border: 1px solid rgba(194, 231, 216, 0.16);
      border-radius: 999px;
      background: rgba(3, 24, 30, 0.42);
      color: rgba(222, 240, 231, 0.65);
      font-size: 11px;
      letter-spacing: 0.04em;
      backdrop-filter: blur(8px);
      pointer-events: none;
    }

    @media (max-width: 600px) {
      .caption {
        top: 20px;
        left: 20px;
      }

      .hint {
        right: 14px;
        bottom: 14px;
      }
    }
  </style>
</head>
<body>
  <div class="caption">
    <h1>Brittle Star</h1>
    <p>Ophiocomina · barrel sponge</p>
  </div>
  <div class="hint">Drag to orbit · Scroll to zoom · Double-click to reset</div>

  <script type="module">
    import * as THREE from "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    // ---------------------------------------------------------------------
    // Renderer and scene
    // ---------------------------------------------------------------------

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: true,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.08;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.domElement.setAttribute("aria-label", "Interactive 3D brittle star and barrel sponge");
    document.body.prepend(renderer.domElement);

    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x072b33, 0.045);

    const camera = new THREE.PerspectiveCamera(
      38,
      window.innerWidth / window.innerHeight,
      0.05,
      100
    );

    // ---------------------------------------------------------------------
    // Lighting
    // ---------------------------------------------------------------------

    scene.add(new THREE.HemisphereLight(0xbce8df, 0x17333a, 1.65));

    const keyLight = new THREE.DirectionalLight(0xfff2d0, 3.4);
    keyLight.position.set(4.5, 8, 5.5);
    keyLight.castShadow = true;
    keyLight.shadow.mapSize.set(2048, 2048);
    keyLight.shadow.camera.left = -6;
    keyLight.shadow.camera.right = 6;
    keyLight.shadow.camera.top = 7;
    keyLight.shadow.camera.bottom = -4;
    keyLight.shadow.camera.near = 0.5;
    keyLight.shadow.camera.far = 22;
    keyLight.shadow.bias = -0.0004;
    scene.add(keyLight);

    const rimLight = new THREE.DirectionalLight(0x75d9d0, 2.1);
    rimLight.position.set(-5, 4, -4);
    scene.add(rimLight);

    const underwaterGlow = new THREE.PointLight(0x55d7c7, 28, 14, 2);
    underwaterGlow.position.set(-2.5, 3.5, 2.5);
    scene.add(underwaterGlow);

    const warmFill = new THREE.PointLight(0xffd79c, 12, 10, 2);
    warmFill.position.set(4, 1.5, -3);
    scene.add(warmFill);

    // ---------------------------------------------------------------------
    // Seafloor and scattered rocks
    // ---------------------------------------------------------------------

    const seafloor = new THREE.Mesh(
      new THREE.CircleGeometry(18, 96),
      new THREE.MeshStandardMaterial({
        color: 0x17383b,
        roughness: 1,
        metalness: 0
      })
    );
    seafloor.rotation.x = -Math.PI / 2;
    seafloor.position.y = -0.055;
    seafloor.receiveShadow = true;
    scene.add(seafloor);

    let randomSeed = 92741;
    function random() {
      randomSeed = (randomSeed * 1664525 + 1013904223) >>> 0;
      return randomSeed / 4294967296;
    }

    const rockGeometry = new THREE.DodecahedronGeometry(0.22, 0);
    const rockMaterials = [
      new THREE.MeshStandardMaterial({ color: 0x294447, roughness: 0.95 }),
      new THREE.MeshStandardMaterial({ color: 0x315052, roughness: 0.92 }),
      new THREE.MeshStandardMaterial({ color: 0x203c40, roughness: 1 })
    ];

    for (let i = 0; i < 12; i++) {
      const angle = random() * Math.PI * 2;
      const radius = 4.2 + random() * 5.5;
      const rock = new THREE.Mesh(
        rockGeometry,
        rockMaterials[Math.floor(random() * rockMaterials.length)]
      );
      rock.position.set(
        Math.cos(angle) * radius,
        0.02 + random() * 0.08,
        Math.sin(angle) * radius
      );
      rock.scale.set(
        0.6 + random() * 1.4,
        0.35 + random() * 0.65,
        0.6 + random() * 1.4
      );
      rock.rotation.set(random() * 3, random() * 3, random() * 3);
      rock.castShadow = true;
      rock.receiveShadow = true;
      scene.add(rock);
    }

    // ---------------------------------------------------------------------
    // Procedural sponge textures
    // ---------------------------------------------------------------------

    function createSpongeTexture() {
      const canvas = document.createElement("canvas");
      canvas.width = canvas.height = 256;
      const ctx = canvas.getContext("2d");
      const image = ctx.createImageData(256, 256);

      for (let i = 0; i < image.data.length; i += 4) {
        const noise = 185 + Math.floor(random() * 38);
        image.data[i] = noise;
        image.data[i + 1] = noise - 12;
        image.data[i + 2] = noise - 28;
        image.data[i + 3] = 255;
      }

      ctx.putImageData(image, 0, 0);

      for (let i = 0; i < 900; i++) {
        const x = random() * 256;
        const y = random() * 256;
        const radius = 0.3 + random() * 2.1;
        ctx.fillStyle = random() > 0.48
          ? `rgba(78,55,34,${0.03 + random() * 0.13})`
          : `rgba(255,235,194,${0.025 + random() * 0.1})`;
        ctx.beginPath();
        ctx.arc(x, y, radius, 0, Math.PI * 2);
        ctx.fill();
      }

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
      texture.repeat.set(3, 2);
      texture.anisotropy = Math.min(8, renderer.capabilities.getMaxAnisotropy());
      return texture;
    }

    const spongeTexture = createSpongeTexture();

    const spongeMaterial = new THREE.MeshStandardMaterial({
      color: 0xc3a374,
      map: spongeTexture,
      bumpMap: spongeTexture,
      bumpScale: 0.065,
      roughness: 0.96,
      metalness: 0
    });

    const rimMaterial = new THREE.MeshStandardMaterial({
      color: 0xd0b07c,
      map: spongeTexture,
      bumpMap: spongeTexture,
      bumpScale: 0.045,
      roughness: 0.94,
      metalness: 0,
      side: THREE.DoubleSide
    });

    const innerSpongeMaterial = new THREE.MeshStandardMaterial({
      color: 0x766348,
      map: spongeTexture,
      bumpMap: spongeTexture,
      bumpScale: 0.035,
      roughness: 1,
      side: THREE.DoubleSide
    });

    // ---------------------------------------------------------------------
    // Barrel sponge: outer wall, hollow interior, porous surface
    // ---------------------------------------------------------------------

    const sponge = new THREE.Group();
    scene.add(sponge);

    const outerGeometry = new THREE.CylinderGeometry(
      2.55,
      2.25,
      2.55,
      96,
      16,
      true
    );

    const outerPositions = outerGeometry.attributes.position;

    for (let i = 0; i < outerPositions.count; i++) {
      const x = outerPositions.getX(i);
      const y = outerPositions.getY(i);
      const z = outerPositions.getZ(i);
      const radius = Math.hypot(x, z);
      const angle = Math.atan2(z, x);

      const irregularity =
        1 +
        0.018 * Math.sin(angle * 9 + y * 2.1) +
        0.012 * Math.sin(angle * 17 - y * 3.3) +
        0.009 * Math.cos(angle * 7 + y * 4.1);

      outerPositions.setXYZ(
        i,
        x * irregularity,
        y + 0.025 * Math.sin(angle * 6 + y * 2.4),
        z * irregularity
      );
    }

    outerGeometry.computeVertexNormals();

    const outerWall = new THREE.Mesh(outerGeometry, spongeMaterial);
    outerWall.castShadow = true;
    outerWall.receiveShadow = true;
    sponge.add(outerWall);

    const innerWall = new THREE.Mesh(
      new THREE.CylinderGeometry(2.18, 2.05, 2.3, 72, 1, true),
      innerSpongeMaterial
    );
    innerWall.position.y = 1.22;
    innerWall.receiveShadow = true;
    sponge.add(innerWall);

    const spongeFloor = new THREE.Mesh(
      new THREE.CircleGeometry(2.14, 72),
      new THREE.MeshStandardMaterial({
        color: 0x65563e,
        map: spongeTexture,
        bumpMap: spongeTexture,
        bumpScale: 0.04,
        roughness: 1
      })
    );
    spongeFloor.rotation.x = -Math.PI / 2;
    spongeFloor.position.y = 0.045;
    spongeFloor.receiveShadow = true;
    sponge.add(spongeFloor);

    function createSpongeRimGeometry(innerRadius, outerRadius, segments = 96) {
      const positions = [];
      const uvs = [];
      const indices = [];

      for (let i = 0; i <= segments; i++) {
        const t = i / segments;
        const angle = t * Math.PI * 2;
        const noise =
          1 +
          0.015 * Math.sin(angle * 8) +
          0.01 * Math.cos(angle * 13 + 0.8);

        const innerX = Math.cos(angle) * innerRadius * noise;
        const innerZ = Math.sin(angle) * innerRadius * noise;
        const outerX = Math.cos(angle) * outerRadius * noise;
        const outerZ = Math.sin(angle) * outerRadius * noise;

        positions.push(innerX, 2.565 + 0.018 * Math.sin(angle * 5), innerZ);
        positions.push(outerX, 2.565 + 0.018 * Math.sin(angle * 5), outerZ);
        uvs.push(0, t, 1, t);

        if (i < segments) {
          const a = i * 2;
          indices.push(a, a + 1, a + 2);
          indices.push(a + 1, a + 3, a + 2);
        }
      }

      const geometry = new THREE.BufferGeometry();
      geometry.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
      geometry.setAttribute("uv", new THREE.Float32BufferAttribute(uvs, 2));
      geometry.setIndex(indices);
      geometry.computeVertexNormals();
      return geometry;
    }

    const spongeRim = new THREE.Mesh(
      createSpongeRimGeometry(2.17, 2.56),
      rimMaterial
    );
    spongeRim.castShadow = true;
    spongeRim.receiveShadow = true;
    sponge.add(spongeRim);

    const roughRim = new THREE.Mesh(
      new THREE.TorusGeometry(2.36, 0.18, 12, 96),
      rimMaterial
    );
    roughRim.rotation.x = Math.PI / 2;
    roughRim.position.y = 2.59;
    roughRim.scale.setScalar(0.97);
    roughRim.castShadow = true;
    roughRim.receiveShadow = true;
    sponge.add(roughRim);

    // Dark pore instances distributed over the sponge wall.
    const poreGeometry = new THREE.SphereGeometry(0.045, 7, 5);
    const poreMaterial = new THREE.MeshStandardMaterial({
      color: 0x35291d,
      roughness: 1
    });

    const poreCount = 320;
    const pores = new THREE.InstancedMesh(poreGeometry, poreMaterial, poreCount);
    const poreMatrix = new THREE.Matrix4();
    const poreQuaternion = new THREE.Quaternion();
    const up = new THREE.Vector3(0, 1, 0);
    const porePosition = new THREE.Vector3();
    const poreNormal = new THREE.Vector3();

    for (let i = 0; i < poreCount; i++) {
      const angle = random() * Math.PI * 2;
      const y = 0.12 + random() * 2.35;
      const radius = THREE.MathUtils.lerp(2.25, 2.55, (y - 0.05) / 2.5);
      const x = Math.cos(angle) * (radius + 0.012);
      const z = Math.sin(angle) * (radius + 0.012);

      porePosition.set(x, y, z);
      poreNormal.set(x / radius, 0, z / radius).normalize();
      poreQuaternion.setFromUnitVectors(up, poreNormal);

      const scale = 0.45 + random() * 0.45;
      poreMatrix.compose(porePosition, poreQuaternion, new THREE.Vector3(scale, scale * 0.45, scale));
      pores.setMatrixAt(i, poreMatrix);

      const shade = 0.35 + random() * 0.28;
      pores.setColorAt(
        i,
        new THREE.Color(shade * 0.72, shade * 0.54, shade * 0.36)
      );
    }

    pores.instanceMatrix.needsUpdate = true;
    pores.instanceColor.needsUpdate = true;
    pores.castShadow = true;
    sponge.add(pores);

    // Fine raised spicules add a natural, uneven sponge texture.
    const spiculeMaterial = new THREE.MeshStandardMaterial({
      color: 0x8b7457,
      roughness: 0.95
    });

    for (let i = 0; i < 30; i++) {
      const angle = random() * Math.PI * 2;
      const y0 = 0.12 + random() * 2.2;
      const y1 = y0 + 0.12 + random() * 0.2;
      const radius0 = THREE.MathUtils.lerp(2.25, 2.55, (y0 - 0.05) / 2.5);
      const radius1 = THREE.MathUtils.lerp(2.25, 2.55, (y1 - 0.05) / 2.5);

      const points = [
        new THREE.Vector3(
          Math.cos(angle) * radius0,
          y0,
          Math.sin(angle) * radius0
        ),
        new THREE.Vector3(
          Math.cos(angle + 0.05) * (radius0 + 0.035),
          y0 + 0.07,
          Math.sin(angle + 0.05) * (radius0 + 0.035)
        ),
        new THREE.Vector3(
          Math.cos(angle - 0.04) * (radius1 + 0.03),
          y1,
          Math.sin(angle - 0.04) * (radius1 + 0.03)
        )
      ];

      const curve = new THREE.CatmullRomCurve3(points);
      const spicule = new THREE.Mesh(
        new THREE.TubeGeometry(curve, 16, 0.008, 4, false),
        spiculeMaterial
      );
      spicule.castShadow = true;
      sponge.add(spicule);
    }

    // ---------------------------------------------------------------------
    // Brittle star
    // ---------------------------------------------------------------------

    const star = new THREE.Group();
    star.position.y = 0.02;
    scene.add(star);

    const starMaterial = new THREE.MeshStandardMaterial({
      color: 0xf0e5ce,
      roughness: 0.72,
      metalness: 0
    });

    const jointMaterial = new THREE.MeshStandardMaterial({
      color: 0xd2c09a,
      roughness: 0.8
    });

    const discGeometry = new THREE.IcosahedronGeometry(0.58, 3);
    const discPositions = discGeometry.attributes.position;

    for (let i = 0; i < discPositions.count; i++) {
      const x = discPositions.getX(i);
      const y = discPositions.getY(i);
      const z = discPositions.getZ(i);

      const distortion =
        1 +
        0.07 * Math.sin(x * 8.1 + z * 5.3) +
        0.045 * Math.cos(y * 9.2 - x * 4.1);

      discPositions.setXYZ(
        i,
        x * distortion,
        y * distortion,
        z * distortion
      );
    }

    discGeometry.computeVertexNormals();

    const disc = new THREE.Mesh(discGeometry, starMaterial);
    disc.scale.set(1, 0.31, 0.94);
    disc.position.set(0, 2.76, 0);
    disc.castShadow = true;
    disc.receiveShadow = true;
    star.add(disc);

    // Small nodules around the central disc.
    const noduleGeometry = new THREE.SphereGeometry(0.055, 8, 6);

    for (let i = 0; i < 18; i++) {
      const angle = (i / 18) * Math.PI * 2 + random() * 0.18;
      const radius = 0.28 + random() * 0.12;
      const nodule = new THREE.Mesh(noduleGeometry, starMaterial);
      nodule.position.set(
        Math.cos(angle) * radius,
        2.81 + random() * 0.025,
        Math.sin(angle) * radius
      );
      nodule.scale.set(1, 0.65, 0.9);
      nodule.castShadow = true;
      star.add(nodule);
    }

    // ---------------------------------------------------------------------
    // Five long, jointed, tapering arms
    // ---------------------------------------------------------------------

    function createTaperedTubeGeometry(
      curve,
      tubularSegments = 28,
      radialSegments = 8,
      radiusStart = 0.095,
      radiusEnd = 0.022
    ) {
      const frames = curve.computeFrenetFrames(tubularSegments, false);
      const positions = [];
      const uvs = [];
      const indices = [];

      for (let i = 0; i <= tubularSegments; i++) {
        const t = i / tubularSegments;
        const point = curve.getPointAt(t);
        const normal = frames.normals[i];
        const binormal = frames.binormals[i];
        const radius = THREE.MathUtils.lerp(
          radiusStart,
          radiusEnd,
          Math.pow(t, 0.84)
        );

        for (let j = 0; j <= radialSegments; j++) {
          const angle = (j / radialSegments) * Math.PI * 2;
          const offset = normal
            .clone()
            .multiplyScalar(Math.cos(angle))
            .addScaledVector(binormal, Math.sin(angle));

          positions.push(
            point.x + offset.x * radius,
            point.y + offset.y * radius,
            point.z + offset.z * radius
          );
          uvs.push(j / radialSegments, t);
        }
      }

      for (let i = 0; i < tubularSegments; i++) {
        for (let j = 0; j < radialSegments; j++) {
          const a = i * (radialSegments + 1) + j;
          const b = (i + 1) * (radialSegments + 1) + j;
          const c = b + 1;
          const d = a + 1;
          const e = d + 1;
          const f = c + 1;

          indices.push(a, d, b, b, d, e, d, e, c);
        }
      }

      const geometry = new THREE.BufferGeometry();
      geometry.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
      geometry.setAttribute("uv", new THREE.Float32BufferAttribute(uvs, 2));
      geometry.setIndex(indices);
      geometry.computeVertexNormals();
      return geometry;
    }

    const armJointGeometry = new THREE.SphereGeometry(0.095, 10, 8);
    const armRingGeometry = new THREE.TorusGeometry(0.073, 0.011, 5, 12);
    const localZ = new THREE.Vector3(0, 0, 1);

    const armConfigurations = [
      {
        angle: 0.34,
        lift: 0.16,
        endHeight: 0.48,
        length: 4.15
      },
      {
        angle: 1.23,
        lift: 0.34,
        endHeight: 0.62,
        length: 4.45
      },
      {
        angle: 2.18,
        lift: 0.12,
        endHeight: 0.36,
        length: 4.05
      },
      {
        angle: 3.18,
        lift: 0.27,
        endHeight: 0.55,
        length: 4.35
      },
      {
        angle: 4.28,
        lift: 0.10,
        endHeight: 0.40,
        length: 4.10
      }
    ];

    for (const config of armConfigurations) {
      const points = [
        new THREE.Vector3(
          Math.cos(config.angle) * 0.43,
          2.73,
          Math.sin(config.angle) * 0.43
        ),
        new THREE.Vector3(
          Math.cos(config.angle) * 0.93,
          3.02 + config.lift,
          Math.sin(config.angle) * 0.93
        ),
        new THREE.Vector3(
          Math.cos(config.angle) * 1.43,
          2.78 + config.lift * 0.5,
          Math.sin(config.angle) * 1.43
        ),
        new THREE.Vector3(
          Math.cos(config.angle) * 1.91,
          2.38 + config.lift * 0.32,
          Math.sin(config.angle) * 1.91
        ),
        new THREE.Vector3(
          Math.cos(config.angle) * 2.28,
          1.72 + config.lift * 0.16,
          Math.sin(config.angle) * 2.28
        ),
        new THREE.Vector3(
          Math.cos(config.angle) * 2.55,
          0.98 + config.endHeight * 0.45,
          Math.sin(config.angle) * 2.55
        ),
        new THREE.Vector3(
          Math.cos(config.angle) * 2.78,
          config.endHeight,
          Math.sin(config.angle) * 2.78
        )
      ];

      const curve = new THREE.CatmullRomCurve3(
        points,
        false,
        "catmullrom",
        0.5
      );

      const arm = new THREE.Mesh(
        createTaperedTubeGeometry(curve),
        starMaterial
      );
      arm.castShadow = true;
      arm.receiveShadow = true;
      star.add(arm);

      // Visible beads and collars emphasize the segmented nature of each arm.
      for (const t of [0.18, 0.37, 0.56, 0.73, 0.88]) {
        const point = curve.getPointAt(t);
        const tangent = curve.getTangentAt(t).normalize();

        const joint = new THREE.Mesh(armJointGeometry, jointMaterial);
        joint.position.copy(point);
        joint.scale.set(1, 0.72, 0.88);
        joint.quaternion.setFromUnitVectors(up, tangent);
        joint.castShadow = true;
        star.add(joint);

        const collar = new THREE.Mesh(armRingGeometry, jointMaterial);
        collar.position.copy(point);
        collar.quaternion.setFromUnitVectors(localZ, tangent);
        collar.scale.setScalar(0.85 + (t - 0.5) * 0.2);
        star.add(collar);
      }

      const tip = new THREE.Mesh(
        new THREE.SphereGeometry(0.026, 7, 5),
        jointMaterial
      );
      tip.position.copy(curve.getPointAt(1));
      star.add(tip);
    }

    // ---------------------------------------------------------------------
    // Suspended marine particles
    // ---------------------------------------------------------------------

    const particleCount = 260;
    const particlePositions = new Float32Array(particleCount * 3);
    const particlePhases = new Float32Array(particleCount);

    for (let i = 0; i < particleCount; i++) {
      particlePositions[i * 3] = (random() - 0.5) * 18;
      particlePositions[i * 3 + 1] = 0.2 + random() * 7;
      particlePositions[i * 3 + 2] = (random() - 0.5) * 18;
      particlePhases[i] = random() * Math.PI * 2;
    }

    const particleGeometry = new THREE.BufferGeometry();
    particleGeometry.setAttribute(
      "position",
      new THREE.BufferAttribute(particlePositions, 3)
    );

    const particles = new THREE.Points(
      particleGeometry,
      new THREE.PointsMaterial({
        color: 0xa5e5d7,
        size: 0.027,
        transparent: true,
        opacity: 0.42,
        depthWrite: false,
        sizeAttenuation: true
      })
    );
    scene.add(particles);

    // Subtle animated caustic rings on the seafloor.
    const causticRings = [];

    for (let i = 0; i < 3; i++) {
      const material = new THREE.MeshBasicMaterial({
        color: 0x83d8c4,
        transparent: true,
        opacity: 0.06,
        side: THREE.DoubleSide,
        depthWrite: false,
        blending: THREE.AdditiveBlending
      });

      const ring = new THREE.Mesh(
        new THREE.RingGeometry(1.8 + i * 0.35, 1.84 + i * 0.35, 96),
        material
      );
      ring.rotation.x = -Math.PI / 2;
      ring.position.set(
        Math.sin(i * 1.7) * 0.6,
        0.012 + i * 0.001,
        Math.cos(i * 1.3) * 0.5
      );
      scene.add(ring);
      causticRings.push(ring);
    }

    // ---------------------------------------------------------------------
    // Camera controls implemented directly without external addons
    // ---------------------------------------------------------------------

    const target = new THREE.Vector3(0, 1.65, 0);
    const spherical = new THREE.Spherical(8.8, 1.13, 0.72);
    let dragging = false;
    let previousX = 0;
    let previousY = 0;

    function updateCamera() {
      spherical.phi = THREE.MathUtils.clamp(spherical.phi, 0.42, 1.47);
      spherical.radius = THREE.MathUtils.clamp(spherical.radius, 5.2, 13.5);
      camera.position.setFromSpherical(spherical).add(target);
      camera.lookAt(target);
    }

    function resetCamera() {
      spherical.set(8.8, 1.13, 0.72);
      updateCamera();
    }

    renderer.domElement.addEventListener("pointerdown", (event) => {
      dragging = true;
      previousX = event.clientX;
      previousY = event.clientY;
      renderer.domElement.setPointerCapture(event.pointerId);
    });

    renderer.domElement.addEventListener("pointermove", (event) => {
      if (!dragging) return;

      const deltaX = event.clientX - previousX;
      const deltaY = event.clientY - previousY;
      previousX = event.clientX;
      previousY = event.clientY;

      spherical.theta -= deltaX * 0.006;
      spherical.phi -= deltaY * 0.005;
      updateCamera();
    });

    function endDrag(event) {
      dragging = false;
      if (event.pointerId !== undefined && renderer.domElement.hasPointerCapture(event.pointerId)) {
        renderer.domElement.releasePointerCapture(event.pointerId);
      }
    }

    renderer.domElement.addEventListener("pointerup", endDrag);
    renderer.domElement.addEventListener("pointercancel", endDrag);

    renderer.domElement.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        spherical.radius *= Math.exp(event.deltaY * 0.001);
        updateCamera();
      },
      { passive: false }
    );

    renderer.domElement.addEventListener("dblclick", resetCamera);

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    updateCamera();

    // ---------------------------------------------------------------------
    // Animation
    // ---------------------------------------------------------------------

    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();

      if (!dragging) {
        spherical.theta += 0.00065;
        updateCamera();
      }

      particles.position.y = Math.sin(elapsed * 0.28) * 0.035;
      particles.rotation.y = Math.sin(elapsed * 0.08) * 0.045;

      star.rotation.z = Math.sin(elapsed * 0.48) * 0.018;
      star.rotation.x = Math.cos(elapsed * 0.37) * 0.012;
      star.rotation.y = Math.sin(elapsed * 0.24) * 0.012;

      causticRings.forEach((ring, index) => {
        const phase = (elapsed * 0.16 + index * 0.71) % 1;
        const scale = 0.94 + phase * 0.18;
        ring.scale.setScalar(scale);
        ring.material.opacity = 0.045 * (1 - phase);
      });

      underwaterGlow.intensity = 27 + Math.sin(elapsed * 0.8) * 3.5;
      warmFill.intensity = 11 + Math.sin(elapsed * 0.55 + 1.2) * 1.4;

      renderer.render(scene, camera);
    }

    animate();
  </script>
